import{_ as t,o as a,c as s,ag as n}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 15 — Lab and Assignment","description":"","frontmatter":{"source":"weeks/15-ship-and-reflect/lab.md"},"headers":[],"relativePath":"weeks/15-ship-and-reflect/lab.md","filePath":"weeks/15-ship-and-reflect/lab.md"}'),i={name:"weeks/15-ship-and-reflect/lab.md"};function r(o,e,h,d,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="week-15--lab-and-assignment" tabindex="-1">Week 15 — Lab and Assignment <a class="header-anchor" href="#week-15--lab-and-assignment" aria-label="Permalink to &quot;Week 15 — Lab and Assignment&quot;">​</a></h1><blockquote><p>The last Lab. Integrate and freeze your team&#39;s contribution, tag a release candidate, write a demo script with a fallback for every step, and rehearse the final presentation on a partner team. Then use what the rehearsal showed you.</p></blockquote><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Nothing in this Lab is scored.</strong> Regulation H-1-a allows no quizzes or exams in the week before finals week, so the dry run is practice only: partner teams ask a practice question, staff coach rather than examine, and no scores or notes on anyone&#39;s answers are kept. What&#39;s graded is the <a href="./../../project/final-presentation.html">final presentation</a> in the final exam period, and the Final&#39;s report and repository.</p></div><p>Bring: the staff comments on your week 14 draft, your evidence table, <code>course/SPEC.md</code>, and every member&#39;s list of their own PRs and <code>AI_LOG.md</code> entries.</p><h2 id="lab--integration-sprint-and-presentation-dry-run-75-min" tabindex="-1">Lab — Integration Sprint and Presentation Dry Run (75 min) <a class="header-anchor" href="#lab--integration-sprint-and-presentation-dry-run-75-min" aria-label="Permalink to &quot;Lab — Integration Sprint and Presentation Dry Run (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Part</th></tr></thead><tbody><tr><td>0:00–0:05</td><td>Part 0: setup check; staff demo of a 2-minute opening (Core)</td></tr><tr><td>0:05–0:25</td><td>Part A: integrate, freeze, tag <code>final-rc</code>, grader&#39;s walk (Core)</td></tr><tr><td>0:25–0:35</td><td>Part B: the demo script (Core)</td></tr><tr><td>0:35–1:00</td><td>Part C: dry run with a partner team (Core)</td></tr><tr><td>(in the slack)</td><td>Part D: act on the feedback (If time)</td></tr><tr><td>1:00–1:10</td><td>Readiness check (not graded)</td></tr><tr><td>1:10–1:15</td><td>Next steps</td></tr></tbody></table><p>If your Seminar&#39;s graduate study talks ran over, the last ones open this Lab; the schedule shifts by their length and Part D becomes homework.</p><h3 id="part-0--setup-check-core-5-min" tabindex="-1">Part 0 — Setup check (Core, 5 min) <a class="header-anchor" href="#part-0--setup-check-core-5-min" aria-label="Permalink to &quot;Part 0 — Setup check (Core, 5 min)&quot;">​</a></h3><ul><li>☐ Your team fork open in a Codespace, <code>main</code> pulled.</li><li>☐ The week 14 draft&#39;s staff comments open, and the evidence table.</li><li>☐ Your partner team for the dry run (posted on Canvas) and where you&#39;ll sit.</li><li>☐ Who presents: any member may, and nobody has to speak if that is a barrier (<a href="./../../project/final-presentation.html#what-to-present">what to present</a>).</li></ul><p>Staff open the Lab with a two-minute example: the first two steps of a demo on a practice fork, the check started at the beginning so its result is ready at the end, and a limitation stated without being asked.</p><p>✅ <strong>Checkpoint:</strong> everyone has the fork open, and your team knows its partner.</p><h3 id="part-a--integrate-freeze-tag-core-20-min" tabindex="-1">Part A — Integrate, freeze, tag (Core, 20 min) <a class="header-anchor" href="#part-a--integrate-freeze-tag-core-20-min" aria-label="Permalink to &quot;Part A — Integrate, freeze, tag (Core, 20 min)&quot;">​</a></h3><p><strong>1. Close out every open PR.</strong> List them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --state</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open</span></span></code></pre></div><p>For each one, decide now:</p><ul><li><strong>Merge</strong> it, if it&#39;s reviewed and CI is green. Hurry is not a reason to skip review: an unreviewed merge in week 15 is exactly what breaks a live demo.</li><li><strong>Finish it in this Lab</strong>, if it&#39;s one small fix away. Name who and by when.</li><li><strong>Close it</strong> with a comment saying why, and move the work to &quot;what we&#39;d do next&quot; in the report&#39;s limitations.</li></ul><p><strong>2. Freeze features.</strong> Write it at the top of <code>course/TASKS.md</code>: &quot;Feature freeze from [date]: fixes only.&quot; From now on, every commit is a fix to something that exists, or a document.</p><p><strong>3. Tag a release candidate</strong> on the merged <code>main</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> final-rc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Release candidate for the final presentation&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> final-rc</span></span></code></pre></div><p><strong>4. Rerun the grader&#39;s walk</strong> from week 14 on <code>final-rc</code>, in a <strong>new</strong> Codespace, by a member who didn&#39;t do it last week:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codespace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [org]/[team-fork] --branch main</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># then, in the new Codespace:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tags</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --detach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> final-rc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[your documented command]</span></span></code></pre></div><p>Compare every number with the evidence table. Anything that moved since the draft needs either a reason in the report or a fix.</p><p>✅ <strong>Checkpoint:</strong> no PR is open without a decision; <code>final-rc</code> is pushed; a fresh Codespace builds it from the README; and the one documented command reproduces the evidence table (or the differences are written down with reasons).</p><p><strong>Troubleshooting.</strong></p><ul><li><strong>Merging two PRs broke the tests:</strong> revert the second merge (<code>git revert -m 1 [merge-commit]</code>), get <code>main</code> green, then fix it on a branch. Don&#39;t debug on <code>main</code> in front of the clock.</li><li><strong>The tag points at the wrong commit:</strong> delete it locally and on the fork (<code>git tag -d final-rc</code> and <code>git push origin :refs/tags/final-rc</code>), then tag again. It&#39;s only a release candidate; the <code>final</code> tag is the one that counts.</li><li><strong>A fresh Codespace is slow to build:</strong> start it first, and do step 1 while it builds (<a href="./../../resources/troubleshooting.html#my-codespace-wont-start-or-im-out-of-hours">troubleshooting</a>).</li></ul><h3 id="part-b--the-demo-script-core-10-min" tabindex="-1">Part B — The demo script (Core, 10 min) <a class="header-anchor" href="#part-b--the-demo-script-core-10-min" aria-label="Permalink to &quot;Part B — The demo script (Core, 10 min)&quot;">​</a></h3><p>The final presentation gives each team <strong>10 minutes</strong> with a live demo, then a minute or two of questions from the room (<a href="./../../project/final-presentation.html#what-to-present">what to present</a>). Write one page your team will hold on the day:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Team [name] · tag: final · check: [command], about [n] min · driver: [username] · timekeeper: [username]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0:00 Start the check: [command]</span></span>
<span class="line"><span>0:15 What we contributed and why (one sentence each) — [username]</span></span>
<span class="line"><span>1:30 Main scenario from SPEC.md: [steps]</span></span>
<span class="line"><span>     Fallback: [the test that shows it / a recorded run]</span></span>
<span class="line"><span>4:30 Edge case: [steps, or the test that exercises it]</span></span>
<span class="line"><span>     Fallback: [...]</span></span>
<span class="line"><span>7:00 The check&#39;s result vs the report: expected [number from section 4]</span></span>
<span class="line"><span>     Fallback: the CI run on the final tag, opened in a tab</span></span>
<span class="line"><span>8:30 The limitation we state first: [one sentence + what it means for a user or maintainer]</span></span>
<span class="line"><span>10:00 Stop.</span></span></code></pre></div><p>Rules of thumb:</p><ul><li><strong>Start the slow check first,</strong> so its result is ready by minute 7.</li><li><strong>One scenario and one edge case,</strong> not a tour of every feature. Feature count doesn&#39;t score (<a href="./../../project/final-presentation.html#the-principle">the principle</a>).</li><li><strong>The limitation is real:</strong> something that doesn&#39;t work, a number you don&#39;t fully trust, a risk you didn&#39;t close. &quot;We ran out of time&quot; isn&#39;t a limitation of the software.</li><li><strong>Every step has a fallback</strong> that doesn&#39;t need the network: a test, a screenshot, a recorded CI run.</li></ul><p>✅ <strong>Checkpoint:</strong> the script fits on one page, every step has a fallback, and the timings add up to 10 minutes.</p><h3 id="part-c--dry-run-with-a-partner-team-core-25-min" tabindex="-1">Part C — Dry run with a partner team (Core, 25 min) <a class="header-anchor" href="#part-c--dry-run-with-a-partner-team-core-25-min" aria-label="Permalink to &quot;Part C — Dry run with a partner team (Core, 25 min)&quot;">​</a></h3><p>Two teams take turns: each half runs <strong>12 minutes</strong>, then you swap.</p><table tabindex="0"><thead><tr><th>Minutes</th><th>Presenting team</th><th>Partner team</th></tr></thead><tbody><tr><td>0–10</td><td>The presentation, strictly timed</td><td>One person keeps time and stops you at 10:00</td></tr><tr><td>10–11</td><td>Answer one question</td><td>Asks one question about a decision in the draft, as the room might</td></tr><tr><td>11–12</td><td>Listen; don&#39;t argue</td><td>Fills in and hands over the feedback cards</td></tr></tbody></table><p><strong>Rules for the dry run:</strong></p><ul><li>🔴 <strong>AI off</strong> for questions, answers and feedback.</li><li><strong>Practice, not assessment.</strong> Nobody scores anyone; staff circulate as coaches and don&#39;t take notes on answers. Anyone may say &quot;pass&quot; to any question.</li><li><strong>Kind and specific.</strong> Ask about the work, never the person. A question someone can&#39;t answer is useful information, not a gotcha.</li></ul><p><strong>Feedback card</strong> (one per partner-team member, given to the presenting team, not to staff):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For team [name] · from [GitHub username]</span></span>
<span class="line"><span>What we saw working:</span></span>
<span class="line"><span>The check: did its result match what you said it would?  yes / partly / no</span></span>
<span class="line"><span>The limitation: was it real, and stated before anyone asked?</span></span>
<span class="line"><span>One answer that convinced us, and why:</span></span>
<span class="line"><span>One question you&#39;ll probably get that you didn&#39;t answer well yet:</span></span>
<span class="line"><span>One thing to cut from the demo:</span></span></code></pre></div><p>✅ <strong>Checkpoint:</strong> both teams ran a full timed presentation and answered a question, and each team holds its partner&#39;s feedback cards.</p><h3 id="part-d--act-on-the-feedback-if-time-10-min" tabindex="-1">Part D — Act on the feedback (If time, 10 min) <a class="header-anchor" href="#part-d--act-on-the-feedback-if-time-10-min" aria-label="Permalink to &quot;Part D — Act on the feedback (If time, 10 min)&quot;">​</a></h3><p>Read the cards together and decide three things:</p><ol><li><strong>One fix</strong> to the software or the check, if the dry run exposed a bug. Fix it on a branch with a review, as usual.</li><li><strong>One cut</strong> from the demo, to buy time for the edge case or the limitation.</li><li><strong>One rehearsal item:</strong> the step that ran long or broke, and its fallback.</li></ol><p>Update the demo script. If time remains, run the demo once more against the clock.</p><h3 id="readiness-check-10-min-not-graded" tabindex="-1">Readiness check (10 min, not graded) <a class="header-anchor" href="#readiness-check-10-min-not-graded" aria-label="Permalink to &quot;Readiness check (10 min, not graded)&quot;">​</a></h3><p>Staff visit each team and note <strong>ready</strong> or <strong>not yet</strong>, only to plan who needs office hours before finals week. They check:</p><ul><li>☐ <code>final-rc</code> is pushed and builds in a fresh Codespace from the README.</li><li>☐ One documented command reproduces the report&#39;s numbers.</li><li>☐ A one-page demo script with a fallback for every step.</li><li>☐ The dry run is done, and the team has its feedback cards.</li></ul><h3 id="next-steps-5-min" tabindex="-1">Next steps (5 min) <a class="header-anchor" href="#next-steps-5-min" aria-label="Permalink to &quot;Next steps (5 min)&quot;">​</a></h3><ul><li><strong>The final exam period:</strong> day, time, room and the order of teams are on Canvas.</li><li><strong>The <code>final</code> tag</strong> must be pushed before the period starts (<a href="#assignment--ready-for-the-final">below</a>).</li><li><strong>Finish your reading response</strong> for this week if you haven&#39;t, and the course survey (anonymous, ungraded).</li></ul><h2 id="assignment--ready-for-the-final" tabindex="-1">Assignment — Ready for the Final <a class="header-anchor" href="#assignment--ready-for-the-final" aria-label="Permalink to &quot;Assignment — Ready for the Final&quot;">​</a></h2><p><strong>Team and individual · the last deliverables of the course.</strong> Everything here is defined in the <a href="./../../project/milestones.html#final">milestones</a> and the <a href="./../../project/final-presentation.html">final presentation</a> pages; if this list and those pages ever disagree, those pages count.</p><h3 id="deliverables-and-deadlines" tabindex="-1">Deliverables and deadlines <a class="header-anchor" href="#deliverables-and-deadlines" aria-label="Permalink to &quot;Deliverables and deadlines&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Deliverable</th><th>Who</th><th>Where</th><th>Due</th></tr></thead><tbody><tr><td><strong>The <code>final</code> tag:</strong> the repository snapshot staff grade and you demo</td><td>Team</td><td>The team fork</td><td><strong>At the start of the final exam period</strong></td></tr><tr><td><strong>The final report</strong> (about 2,000–3,500 words, nine sections)</td><td>Team</td><td>Canvas</td><td><strong>At the start of the final exam period</strong></td></tr><tr><td><strong>Peer evaluation 3</strong> (🔴 AI off)</td><td>Each member</td><td>Canvas</td><td><strong>At the start of the final exam period</strong></td></tr><tr><td><strong>The final paper</strong> (4–6 pages, ACM format, with the artifact link)</td><td>CS [5xxx]</td><td>Canvas</td><td><strong>At the start of the final exam period</strong></td></tr><tr><td><strong>The presentation,</strong> with your demo script and fallbacks</td><td>Team</td><td>The final exam period</td><td>The period</td></tr><tr><td><strong>Upstream PRs:</strong> answer review, or close politely with a note</td><td>Each member with one</td><td>On the PR</td><td>By the end of the term</td></tr></tbody></table><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li><p><strong>Fix what the dry run found,</strong> with reviews and green CI, then stop. No features after the freeze.</p></li><li><p><strong>Push the <code>final</code> tag</strong> on the commit you&#39;ll demo:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> final</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Final snapshot for the final presentation&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> final</span></span></code></pre></div><p>Staff record the commit <code>final</code> points to at the start of the period, and that commit is what&#39;s graded (<a href="./../../project/milestones.html#the-repository-snapshot">the repository snapshot</a>). Don&#39;t move it after the period starts.</p></li><li><p><strong>Run the grader&#39;s walk one last time</strong> on <code>final</code>, in a fresh Codespace: build from the README, run the one documented command, compare with the report.</p></li><li><p><strong>Rehearse the presentation</strong> against the clock, with the fallbacks, on the <code>final</code> tag (<a href="./../../project/final-presentation.html#what-to-present">what to present</a>).</p></li><li><p><strong>Finish the final report</strong> from the draft and the staff comments (<a href="./../../project/milestones.html#the-final-report">the final report</a>). 🟡 AI limited: AI may help with tables, figures and checking claims against the fork. 🔴 AI off: the limitations, contributions and reflection sections, written by the team. Every number must be reproducible from the <code>final</code> tag.</p></li><li><p><strong>Submit peer evaluation 3</strong> on Canvas: a 1–5 rating for each teammate and yourself on each criterion, each with one sentence of evidence (<a href="./../../assessment/rubrics.html#peer-evaluation">criteria</a>).</p></li><li><p><strong>CS [5xxx]:</strong> finish the paper from your draft and its feedback, report every deviation from your protocol, and link the artifact (<a href="./../../graduate/empirical-study.html#the-paper">the paper</a>).</p></li></ol><h3 id="how-its-graded" tabindex="-1">How it&#39;s graded <a class="header-anchor" href="#how-its-graded" aria-label="Permalink to &quot;How it&#39;s graded&quot;">​</a></h3><p>The Final is <strong>45 points</strong>, all Team: report and repository <strong>35</strong> and the presentation <strong>10</strong> (<a href="./../../assessment/rubrics.html#final-report-and-repository">report rubric</a>; <a href="./../../project/final-presentation.html#rubric">presentation rubric</a>). The rows reward demonstrated behavior, reproducible checks, engineering decisions with evidence, honest limitations and an accurate process record, not feature count, repository size or token spend. A missing peer evaluation costs you 2 points of the Final. No grace token applies to the Final (<a href="./../../assessment/#late-work-and-grace-tokens">late work</a>).</p><p><strong>There&#39;s no Seminar next week</strong> (finals week), so the usual &quot;Due before next week&#39;s Seminar (default 11:59 pm the night before)&quot; doesn&#39;t apply this week: each deliverable has its own deadline in the table above.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Minimum to keep up:</strong> a <code>final</code> tag that builds from your README in a fresh Codespace, one check you can rerun live with a result that matches your report, one honest limitation, and every member able to explain their own PR. If you&#39;re behind, shrink the claim: a small contribution that works and that you can explain scores better than a large one you can&#39;t verify. Tell the instructor before the final exam period, not during it.</p></div>`,58)])])}const m=t(i,[["render",r]]);export{g as __pageData,m as default};
